sha=$(curl -s -H "Authorization: token $GITHUB_TOKEN" https://api.github.com/repos/missingbulb/TLDR/pulls/586 | node -e 'let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>console.log(JSON.parse(d).head.sha))')
echo "watching sha $sha"
for i in $(seq 1 20); do
  out=$(curl -s -H "Authorization: token $GITHUB_TOKEN" "https://api.github.com/repos/missingbulb/TLDR/commits/$sha/check-runs")
  node -e '
    let d="";process.stdin.on("data",c=>d+=c);
    process.stdin.on("end",()=>{
      const j=JSON.parse(d);
      const runs=j.check_runs||[];
      console.log("runs:"+runs.length+" "+runs.map(r=>r.name+":"+r.status+"/"+r.conclusion).join(", "));
      const allDone = runs.length>0 && runs.every(r=>r.status==="completed");
      if(allDone) console.log("ALL_DONE");
    })
  ' <<< "$out"
  if [ $? -ne 0 ]; then :; fi
  donecheck=$(echo "$out" | node -e 'let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{const j=JSON.parse(d);const runs=j.check_runs||[];console.log(runs.length>0 && runs.every(r=>r.status==="completed")?"yes":"no")})')
  if [ "$donecheck" = "yes" ]; then
    echo "ALL_CHECKS_CONCLUDED"
    break
  fi
  sleep 20
done

